import unittest
import json
import time
from app import webserver

class TestWebserver(unittest.TestCase):
    
    def setUp(self):
        """Set up test client"""
        self.client = webserver.test_client()
        
    def verify_job_result(self, job_id, expected_result, max_retries=15, delay=0.2):
        """Helper function to get job results and verify against expected result"""

        # Check if the job completed in less than 15 tries
        for _ in range(max_retries):

            response = self.client.get(f'/api/get_results/{job_id}')

            # Check response status code for "get_results" route
            self.assertEqual(response.status_code, 200)
            
            result_data = json.loads(response.data)
            
            # Check if job has completed sucessfully
            if 'status' in result_data:
                if result_data['status'] == 'done':
                    self.assertIn('data', result_data)
                    actual_result = result_data['data']
                    self.assertEqual(actual_result, expected_result)
                    return
                elif result_data['status'] == 'running':
                    time.sleep(delay)
                    continue
                else:
                    self.fail(f"Job status error")
            else:
                self.fail("Response missing 'status' field")
        
        self.fail(f"Job result not available after {max_retries} retries")
    
    def test_state_mean_request(self):
        """Test state_mean_request"""
        # Test data from input test files
        test_data = {
            "question": "Percent of adults who report consuming fruit less than one time daily",
            "state": "Wyoming"
        }
        
        # Send POST request to the endpoint
        response = self.client.post(
            '/api/state_mean',
            data=json.dumps(test_data),
            content_type='application/json'
        )
        
        # Check response status code
        self.assertEqual(response.status_code, 200)
        
        # Get job_id from response
        response_data = json.loads(response.data)
        self.assertIn('job_id', response_data)
        job_id = response_data['job_id']
        
        # Expected result from output test files
        expected_result = {"Wyoming": 41.93529411764706}
        
        self.verify_job_result(job_id, expected_result)
    
