    def test_state_mean_by_category_request(self):
        """Test state_mean_by_category_request"""
        test_data = {"question": "Percent of adults who achieve at least 300 minutes a week of moderate-intensity aerobic physical activity or 150 minutes a week of vigorous-intensity aerobic activity (or an equivalent combination)", "state": "West Virginia"}
        
